using System.ComponentModel;
using System.Net;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var tools = new ResearchTools();
var agent = new ChatClientAgent(chatClient, tools: [.. tools.GetTools()]);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       Research Agent (MAF + MEAI)     ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine("Enter a research topic (or 'quit' to exit):\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    tools.ClearNotes();

    var history = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. When given a topic you MUST:
            1. Search the web for information on the topic (2-3 searches with different queries).
            2. Save key findings as notes using the note-taking tool.
            3. After gathering enough information, produce a structured summary that
               references the notes you saved.
            Always search before summarizing. Be thorough but concise.
            """),
        new(ChatRole.User, $"Research the following topic: {topic}"),
    };

    var options = new AgentInvokeOptions { MaximumIterations = 10 };

    Console.WriteLine($"\n🔍 Researching: {topic}\n");

    try
    {
        await foreach (var message in agent.InvokeStreamingAsync(history, options))
        {
            if (!string.IsNullOrEmpty(message.Text))
                Console.Write(message.Text);
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n⚠ Agent error: {ex.Message}");
    }

    Console.WriteLine("\n");

    var notes = tools.GetNotes();
    if (notes.Count > 0)
    {
        Console.WriteLine("📝 Saved Research Notes:");
        Console.WriteLine(new string('─', 40));
        foreach (var (i, note) in notes.Select((n, i) => (i + 1, n)))
            Console.WriteLine($"  {i}. {note}");
        Console.WriteLine(new string('─', 40));
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// ── Tool implementations ───────────────────────────────────────────

sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _http = new();

    public IReadOnlyList<string> GetNotes() => _notes.AsReadOnly();
    public void ClearNotes() => _notes.Clear();

    public IEnumerable<AIFunction> GetTools() =>
    [
        AIFunctionFactory.Create(SearchWebAsync),
        AIFunctionFactory.Create(SaveNote),
        AIFunctionFactory.Create(GetAllNotes),
    ];

    [Description("Search the web for information on a query. Returns a list of result titles, URLs, and snippets.")]
    private async Task<string> SearchWebAsync(
        [Description("The search query")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://lite.duckduckgo.com/lite?q={encoded}";

        try
        {
            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var response = await _http.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync(cancellationToken);

            // Extract text snippets from the lite HTML results
            var results = ParseLiteResults(html);

            if (results.Count == 0)
                return $"No results found for '{query}'.";

            return string.Join("\n\n", results.Take(5));
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. " +
                   "Try rephrasing the query or use a different search term.";
        }
    }

    [Description("Save a research note. Use this to record important findings during research.")]
    private string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all previously saved research notes.")]
    private string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n",
            _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }

    private static List<string> ParseLiteResults(string html)
    {
        var results = new List<string>();

        // DuckDuckGo Lite uses simple table rows with class="result-snippet"
        // and anchor tags for links. Parse pragmatically.
        var lines = html.Split('\n');
        string? currentTitle = null;
        string? currentUrl = null;

        foreach (var rawLine in lines)
        {
            var line = rawLine.Trim();

            // Extract links from result link anchors
            if (line.Contains("class=\"result-link\"", StringComparison.OrdinalIgnoreCase)
                || line.Contains("class='result-link'", StringComparison.OrdinalIgnoreCase))
            {
                var href = ExtractAttribute(line, "href");
                var text = StripHtml(line);
                if (!string.IsNullOrWhiteSpace(text))
                    currentTitle = text;
                if (!string.IsNullOrWhiteSpace(href))
                    currentUrl = href;
            }
            else if (line.Contains("result-snippet", StringComparison.OrdinalIgnoreCase))
            {
                var snippet = StripHtml(line);
                if (!string.IsNullOrWhiteSpace(snippet))
                {
                    var entry = $"Title: {currentTitle ?? "N/A"}\nURL: {currentUrl ?? "N/A"}\nSnippet: {snippet}";
                    results.Add(entry);
                    currentTitle = null;
                    currentUrl = null;
                }
            }
        }

        // Fallback: if structured parsing found nothing, extract any readable text
        if (results.Count == 0)
        {
            var plainText = StripHtml(html);
            if (plainText.Length > 100)
                results.Add($"Web content: {plainText[..Math.Min(2000, plainText.Length)]}");
        }

        return results;
    }

    private static string? ExtractAttribute(string html, string attr)
    {
        var marker = $"{attr}=\"";
        var start = html.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
        if (start < 0) return null;
        start += marker.Length;
        var end = html.IndexOf('"', start);
        return end > start ? html[start..end] : null;
    }

    private static string StripHtml(string html)
    {
        var text = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
        text = WebUtility.HtmlDecode(text);
        return System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ").Trim();
    }
}

