IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var tools = new ResearchTools();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic you MUST:
        1. Search the web for information on the topic (2-3 searches with different queries).
        2. Save key findings as notes using the note-taking tool.
        3. After gathering enough information, produce a structured summary that
           references the notes you saved.
        Always search before summarizing. Be thorough but concise.
        """,
