88. sealed class ResearchTools
89. {
90.     private readonly List<string> _notes = [];
91.     private readonly HttpClient _http = new();
92. 
93.     public IReadOnlyList<string> GetNotes() => _notes.AsReadOnly();
94.     public void ClearNotes() => _notes.Clear();
95. 
96.     public IEnumerable<AIFunction> GetTools() =>
97.     [
98.         AIFunctionFactory.Create(SearchWebAsync),
99.         AIFunctionFactory.Create(SaveNote),
100.         AIFunctionFactory.Create(GetAllNotes),
101.     ];
102. 
103.     [Description("Search the web for information on a query. Returns a list of result titles, URLs, and snippets.")]
104.     private async Task<string> SearchWebAsync(
105.         [Description("The search query")] string query,
106.         CancellationToken cancellationToken = default)
107.     {
108.         Console.WriteLine($"  🌐 Searching: \"{query}\"");
109. 
110.         var encoded = WebUtility.UrlEncode(query);
111.         var url = $"https://lite.duckduckgo.com/lite?q={encoded}";
112. 
113.         try
114.         {
115.             using var request = new HttpRequestMessage(HttpMethod.Get, url);
116.             request.Headers.UserAgent.ParseAdd(
117.                 "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
118. 
119.             var response = await _http.SendAsync(request, cancellationToken);
120.             response.EnsureSuccessStatusCode();
121. 
122.             var html = await response.Content.ReadAsStringAsync(cancellationToken);
123.             var results = ParseLiteResults(html);
124. 
125.             if (results.Count == 0)
126.                 return $"No results found for '{query}'.";
127. 
128.             return string.Join("\n\n", results.Take(5));
129.         }
130.         catch (Exception ex)
131.         {
132.             return $"Search failed: {ex.Message}. " +
133.                    "Try rephrasing the query or use a different search term.";
134.         }
135.     }
136. 
137.     [Description("Save a research note. Use this to record important findings during research.")]
138.     private string SaveNote(
139.         [Description("The note content to save")] string note)
140.     {
141.         _notes.Add(note);
142.         Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
143.         return $"Note saved successfully. You now have {_notes.Count} note(s).";
144.     }
145. 
146.     [Description("Retrieve all previously saved research notes.")]
147.     private string GetAllNotes()
148.     {
149.         if (_notes.Count == 0)
150.             return "No notes saved yet.";
151. 
152.         return string.Join("\n",
153.             _notes.Select((n, i) => $"Note {i + 1}: {n}"));
154.     }
155. 
156.     private static List<string> ParseLiteResults(string html)
157.     {
158.         var results = new List<string>();
159. 
160.         var lines = html.Split('\n');
161.         string? currentTitle = null;
162.         string? currentUrl = null;
163. 
164.         foreach (var rawLine in lines)
165.         {
166.             var line = rawLine.Trim();
167. 
168.             if (line.Contains("class=\"result-link\"", StringComparison.OrdinalIgnoreCase)
169.                 || line.Contains("class='result-link'", StringComparison.OrdinalIgnoreCase))
170.             {
171.                 var href = ExtractAttribute(line, "href");
172.                 var text = StripHtml(line);
173.                 if (!string.IsNullOrWhiteSpace(text))
174.                     currentTitle = text;
175.                 if (!string.IsNullOrWhiteSpace(href))
176.                     currentUrl = href;
177.             }
178.             else if (line.Contains("result-snippet", StringComparison.OrdinalIgnoreCase))
179.             {
180.                 var snippet = StripHtml(line);
181.                 if (!string.IsNullOrWhiteSpace(snippet))
182.                 {
183.                     var entry = $"Title: {currentTitle ?? "N/A"}\nURL: {currentUrl ?? "N/A"}\nSnippet: {snippet}";
184.                     results.Add(entry);
185.                     currentTitle = null;
186.                     currentUrl = null;
187.                 }
188.             }
189.         }
190. 
191.         if (results.Count == 0)
192.         {
193.             var plainText = StripHtml(html);
194.             if (plainText.Length > 100)
195.                 results.Add($"Web content: {plainText[..Math.Min(2000, plainText.Length)]}");
196.         }
197. 
198.         return results;
199.     }
200. 
201.     private static string? ExtractAttribute(string html, string attr)
202.     {
203.         var marker = $"{attr}=\"";
204.         var start = html.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
205.         if (start < 0) return null;
206.         start += marker.Length;
207.         var end = html.IndexOf('"', start);
208.         return end > start ? html[start..end] : null;
209.     }
210. 
211.     private static string StripHtml(string html)
212.     {
213.         var text = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
214.         text = WebUtility.HtmlDecode(text);
215.         return System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ").Trim();
216.     }
217. }
