     [
         AIFunctionFactory.Create(SearchWebAsync),
         AIFunctionFactory.Create(SaveNote),
         AIFunctionFactory.Create(GetAllNotes),
     ];

     [Description("Search the web for information on a query. Returns a list of result titles, URLs, and snippets.")]
     private async Task<string> SearchWebAsync(
         [Description("The search query")] string query,
         CancellationToken cancellationToken = default)
     {
         Console.WriteLine($"  🌐 Searching: \"{query}\"");

         var encoded = WebUtility.UrlEncode(query);
         var url = $"https://lite.duckduckgo.com/lite?q={encoded}";

         try
         {
             using var request = new HttpRequestMessage(HttpMethod.Get, url);
             request.Headers.UserAgent.ParseAdd(
                 "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

             var response = await _http.SendAsync(request, cancellationToken);
             response.EnsureSuccessStatusCode();

             var html = await response.Content.ReadAsStringAsync(cancellationToken);
             var results = ParseLiteResults(html);

             if (results.Count == 0)
                 return $"No results found for '{query}'.";

             return string.Join("\n\n", results.Take(5));
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}. " +
                    "Try rephrasing the query or use a different search term.";
         }
     }

     [Description("Save a research note. Use this to record important findings during research.")]
     private string SaveNote(
         [Description("The note content to save")] string note)
     {
         _notes.Add(note);
         Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
         return $"Note saved successfully. You now have {_notes.Count} note(s).";
     }

     [Description("Retrieve all previously saved research notes.")]
     private string GetAllNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         return string.Join("\n",
             _notes.Select((n, i) => $"Note {i + 1}: {n}"));
     }

     private static List<string> ParseLiteResults(string html)
     {
         var results = new List<string>();

         var lines = html.Split('\n');
         string? currentTitle = null;
         string? currentUrl = null;

         foreach (var rawLine in lines)
         {
             var line = rawLine.Trim();

             if (line.Contains("class=\"result-link\"", StringComparison.OrdinalIgnoreCase)
                 || line.Contains("class='result-link'", StringComparison.OrdinalIgnoreCase))
             {
                 var href = ExtractAttribute(line, "href");
                 var text = StripHtml(line);
                 if (!string.IsNullOrWhiteSpace(text))
                     currentTitle = text;
                 if (!string.IsNullOrWhiteSpace(href))
                     currentUrl = href;
             }
             else if (line.Contains("result-snippet", StringComparison.OrdinalIgnoreCase))
             {
                 var snippet = StripHtml(line);
                 if (!string.IsNullOrWhiteSpace(snippet))
                 {
                     var entry = $"Title: {currentTitle ?? "N/A"}\nURL: {currentUrl ?? "N/A"}\nSnippet: {snippet}";
                     results.Add(entry);
                     currentTitle = null;
                     currentUrl = null;
                 }
             }
         }

         if (results.Count == 0)
         {
             var plainText = StripHtml(html);
             if (plainText.Length > 100)
                 results.Add($"Web content: {plainText[..Math.Min(2000, plainText.Length)]}");
         }

         return results;
     }

     private static string? ExtractAttribute(string html, string attr)
     {
         var marker = $"{attr}=\"";
         var start = html.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
         if (start < 0) return null;
         start += marker.Length;
         var end = html.IndexOf('"', start);
         return end > start ? html[start..end] : null;
     }

     private static string StripHtml(string html)
     {
         var text = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
         text = WebUtility.HtmlDecode(text);
         return System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ").Trim();
